import java.util.*;

public class Main {
    static final int MAX_SIZE = 7100;
    static final long INF = 1000000000L;
    static char[][] g1 = new char[15][15];
    static char[][] g2 = new char[15][15];
    static boolean[][] visitedGrid = new boolean[15][15];
    static int[][] distGrid = new int[15][15];
    static int n, t;
    static int[] tgt;

    static class Maxflow {
        static class Edge {
            int from, to;
            long flow, capacity;
            Edge(int from, int to, long flow, long capacity) {
                this.from = from;
                this.to = to;
                this.flow = flow;
                this.capacity = capacity;
            }
        }

        int s, t;
        ArrayList<Edge> edg = new ArrayList<>();
        ArrayList<Integer>[] g = new ArrayList[MAX_SIZE];
        int[] dist = new int[MAX_SIZE];
        int[] visited = new int[MAX_SIZE];
        int[] cur = new int[MAX_SIZE];

        void init() {
            edg.clear();
            for (int i = 0; i < MAX_SIZE; i++) {
                g[i] = new ArrayList<>();
            }
        }

        void addedge(int from, int to, long capacity) {
            edg.add(new Edge(from, to, 0, capacity));
            edg.add(new Edge(to, from, 0, 0));
            g[from].add(edg.size() - 2);
            g[to].add(edg.size() - 1);
        }

        boolean bfs() {
            Arrays.fill(visited, 0);
            Arrays.fill(dist, 0);
            Queue<Integer> q = new LinkedList<>();
            q.add(s);
            visited[s] = 1;
            dist[s] = 0;
            while (!q.isEmpty()) {
                int v = q.poll();
                for (int idx : g[v]) {
                    Edge e = edg.get(idx);
                    int nxt = e.to;
                    if (visited[nxt] == 0 && e.capacity > e.flow) {
                        dist[nxt] = dist[v] + 1;
                        q.add(nxt);
                        visited[nxt] = 1;
                    }
                }
            }
            return visited[t] == 1;
        }

        long dfs(int x, long cp) {
            if (x == t || cp == 0) return cp;
            long flow = 0, newflow;
            for (int y = cur[x]; y < g[x].size(); y++) {
                cur[x] = y;
                Edge e = edg.get(g[x].get(y));
                if (dist[x] + 1 == dist[e.to]) {
                    long minn = Math.min(cp, e.capacity - e.flow);
                    newflow = dfs(e.to, minn);
                    if (newflow > 0) {
                        e.flow += newflow;
                        edg.get(g[x].get(y) ^ 1).flow -= newflow;
                        flow += newflow;
                        cp -= newflow;
                        if (cp == 0) break;
                    }
                }
            }
            return flow;
        }

        long Dinic() {
            long flow = 0;
            while (bfs()) {
                Arrays.fill(cur, 0);
                flow += dfs(s, INF);
            }
            return flow;
        }
    }

    static void BFS(int x, int y) {
        for (int i = 0; i < 15; i++) {
            Arrays.fill(distGrid[i], 111);
        }
        // visitedGrid is already false initially
        Queue<int[]> q = new LinkedList<>();
        q.add(new int[]{x, y, 0});
        distGrid[x][y] = 0;
        int[] dx = {1, 0, 0, -1};
        int[] dy = {0, 1, -1, 0};
        while (!q.isEmpty()) {
            int[] p = q.poll();
            int cx = p[0], cy = p[1], d = p[2];
            if (visitedGrid[cx][cy]) continue;
            visitedGrid[cx][cy] = true;
            distGrid[cx][cy] = d;
            for (int i = 0; i < 4; i++) {
                int tx = cx + dx[i];
                int ty = cy + dy[i];
                if (tx <= 0 || tx > n || ty <= 0 || ty > n || visitedGrid[tx][ty] || g1[tx][ty] == 'Y')
                    continue;
                q.add(new int[]{tx, ty, d + 1});
            }
        }
    }

    static int index(int level, int x, int y) {
        return level * n * n + (x - 1) * n + y;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        t = sc.nextInt();
        sc.nextLine();
        for (int i = 1; i <= n; i++) {
            String line = sc.next();
            for (int j = 1; j <= n; j++) {
                g1[i][j] = line.charAt(j - 1);
            }
        }
        for (int i = 1; i <= n; i++) {
            String line = sc.next();
            for (int j = 1; j <= n; j++) {
                g2[i][j] = line.charAt(j - 1);
            }
        }

        Maxflow mf = new Maxflow();
        mf.init();
        mf.s = 0;
        mf.t = MAX_SIZE - 2;

        int x = 0, y = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (g1[i][j] == 'Z') {
                    x = i;
                    y = j;
                    break;
                }
            }
        }

        tgt = new int[n * n + 1];
        for (int i = 1; i <= n * n; i++) {
            tgt[i] = MAX_SIZE - 3 - (n * n - i);
        }

        BFS(x, y);

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (g1[i][j] >= '0' && g1[i][j] <= '9')
                    mf.addedge(mf.s, index(0, i, j), g1[i][j] - '0');
                if (g2[i][j] >= '0' && g2[i][j] <= '9')
                    mf.addedge(tgt[index(0, i, j)], mf.t, g2[i][j] - '0');
                mf.addedge(index(0, i, j), tgt[index(0, i, j)], INF);
            }
        }

        int[] dx = {1, 0, 0, -1};
        int[] dy = {0, 1, -1, 0};
        for (int i = 1; i <= t; i++) {
            for (int j = 1; j <= n; j++) {
                for (int k = 1; k <= n; k++) {
                    if (g1[j][k] == 'Y' || g1[j][k] == 'Z') continue;
                    for (int l = 0; l < 4; l++) {
                        int tx = dx[l] + j;
                        int ty = dy[l] + k;
                        if (tx >= 1 && tx <= n && ty >= 1 && ty <= n && g1[tx][ty] != 'Y' && g1[tx][ty] != 'Z') {
                            if (distGrid[j][k] >= i && distGrid[tx][ty] >= i) {
                                mf.addedge(index(i - 1, tx, ty), index(i, j, k), INF);
                            }
                        }
                    }
                    mf.addedge(index(i, j, k), tgt[index(0, j, k)], INF);
                }
            }
        }
        System.out.println(mf.Dinic());
    }
}
